export const DEFAULTS={rounds:10,mode:'intro',lengths:[.1,.5,1,3],points:[1000,900,800,500]};
export function normalize(s){return s.normalize('NFKD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/\([^)]*\)|\[[^\]]*\]/g,'').replace(/[^\p{L}\p{N}]/gu,'');}
export function distance(a,b){let row=Array.from({length:b.length+1},(_,i)=>i);for(let i=1;i<=a.length;i++){let prev=row[0];row[0]=i;for(let j=1;j<=b.length;j++){const old=row[j];row[j]=Math.min(row[j]+1,row[j-1]+1,prev+(a[i-1]===b[j-1]?0:1));prev=old;}}return row[b.length];}
export function matches(guess,title,artist=''){let g=normalize(guess),t=normalize(title);if(!g||!t)return false;return [t,normalize(title+' '+artist),normalize(artist+' '+title)].some(v=>g===v||(v.length>=5&&distance(g,v)<=Math.max(1,Math.floor(v.length*.18))));}
export function shuffle(items,random=Math.random){const a=[...items];for(let i=a.length-1;i>0;i--){const j=Math.floor(random()*(i+1));[a[i],a[j]]=[a[j],a[i]];}return a;}
export function parseCSV(text){const rows=[];let row=[],field='',quote=false;for(let i=0;i<text.length;i++){let c=text[i];if(c==='"'){if(quote&&text[i+1]==='"'){field+='"';i++;}else quote=!quote;}else if(c===','&&!quote){row.push(field);field='';}else if((c==='\n'||c==='\r')&&!quote){if(c==='\r'&&text[i+1]==='\n')i++;row.push(field);if(row.some(Boolean))rows.push(row);row=[];field='';}else field+=c;}if(quote)throw Error('CSV has an unclosed quoted field.');row.push(field);if(row.some(Boolean))rows.push(row);return rows;}
export function csvTracks(text){const rows=parseCSV(text);if(rows.length<2)throw Error('CSV needs a header and at least one track.');const h=rows.shift().map(s=>s.replace(/^\uFEFF/,'').trim().toLowerCase());const ti=h.findIndex(s=>['track name','track','title','song name','name'].includes(s)),ar=h.findIndex(s=>['artist name(s)','artist name','artists','artist'].includes(s));if(ti<0)throw Error('Add a Track Name or Title column to your CSV.');return rows.filter(r=>r[ti]?.trim()).map(r=>({title:r[ti].trim(),artist:r[ar]?.trim()||'Unknown artist',source:'metadata'}));}
export function roundStart(duration,maxLength,mode,random=Math.random){return mode==='random'?random()*Math.max(0,duration-maxLength):0;}
export function uniqueTracks(tracks){const seen=new Set();return tracks.filter(t=>{const k=t.videoId?'yt:'+t.videoId:normalize(t.title)+'|'+normalize(t.artist);if(seen.has(k))return false;seen.add(k);return true;});}
